from typing import List, Tuple
from itertools import combinations, product

def can_tile_grid(n: int, h: int, w: int, tiles: List[Tuple[int, int]]) -> bool:
    """ Determine if it's possible to place rectangular tiles on an H×W grid such that:
    - Every cell is covered by exactly one tile
    - Tiles can be rotated (so a 2×3 tile can be placed as 3×2)
    - Some tiles may remain unused
    - Tiles must be aligned with grid cells and cannot extend outside

    Args:
        n: Number of available tiles (1 ≤ n ≤ 7)
        h: Height of the grid (1 ≤ h ≤ 10)
        w: Width of the grid (1 ≤ w ≤ 10)
        tiles: List of (a, b) tuples where tile i has dimensions a×b (1 ≤ a, b ≤ 10)

    Returns:
        True if the grid can be perfectly tiled, False otherwise

    >>> can_tile_grid(5, 5, 5, [(1, 1), (3, 3), (4, 4), (2, 3), (2, 5)])
    True
    >>> can_tile_grid(1, 1, 2, [(2, 3)])
    False
    >>> can_tile_grid(1, 2, 2, [(1, 1)])
    False
    """

    total_area = h * w

    for k in range(1, n + 1):
        for subset in combinations(tiles, k):
            subset_area = sum(a * b for a, b in subset)
            if subset_area != total_area:
                continue

            # Generate all possible orientations for each tile in the subset
            orientations = []
            for tile in subset:
                a, b = tile
                orientations.append([(a, b), (b, a)])

            for orientation_combination in product(*orientations):
                if can_arrange(orientation_combination, h, w):
                    return True

    return False

def can_arrange(tiles: List[Tuple[int, int]], h: int, w: int) -> bool:
    grid = [[False for _ in range(w)] for _ in range(h)]

    def backtrack(remaining, grid):
        # Find the first empty cell
        for i in range(h):
            for j in range(w):
                if not grid[i][j]:
                    # Try placing each tile in remaining
                    for idx in range(len(remaining)):
                        a, b = remaining[idx]
                        # Try original orientation
                        if i + a <= h and j + b <= w:
                            can_place = True
                            for x in range(i, i + a):
                                for y in range(j, j + b):
                                    if grid[x][y]:
                                        can_place = False
                                        break
                                if not can_place:
                                    break
                            if can_place:
                                # Place the tile
                                for x in range(i, i + a):
                                    for y in range(j, j + b):
                                        grid[x][y] = True
                                new_remaining = remaining[:idx] + remaining[idx+1:]
                                if backtrack(new_remaining, grid):
                                    return True
                                # Undo placement
                                for x in range(i, i + a):
                                    for y in range(j, j + b):
                                        grid[x][y] = False
                        # Try rotated orientation
                        a, b = b, a
                        if i + a <= h and j + b <= w:
                            can_place = True
                            for x in range(i, i + a):
                                for y in range(j, j + b):
                                    if grid[x][y]:
                                        can_place = False
                                        break
                                if not can_place:
                                    break
                            if can_place:
                                # Place the tile
                                for x in range(i, i + a):
                                    for y in range(j, j + b):
                                        grid[x][y] = True
                                new_remaining = remaining[:idx] + remaining[idx+1:]
                                if backtrack(new_remaining, grid):
                                    return True
                                # Undo placement
                                for x in range(i, i + a):
                                    for y in range(j, j + b):
                                        grid[x][y] = False
                    return False  # No tile could be placed at this position
        return True  # All cells are filled

    return backtrack(tiles, grid)
