            if l > length:
                continue
            upper = int(s[:l]) if l == length else 10**l - 1
            if upper < 10**(l-1):
                continue
            digits = list(map(int, str(upper)))
            @lru_cache(maxsize=None)
            def dp(pos, tight, even_odd_diff, rem, leading_zero):
                if pos == l:
                    return 1 if (even_odd_diff == 0 and rem == 0) else 0
                limit = digits[pos] if tight else 9
                res = 0
                for d in range(0, limit + 1):
                    new_tight = tight and (d == limit)
                    new_even_odd_diff = even_odd_diff
                    new_rem = rem
                    new_leading_zero = leading_zero and (d == 0)
                    if not new_leading_zero:
                        if d % 2 == 0:
                            new_even_odd_diff += 1
                        else:
                            new_even_odd_diff -= 1
                        new_rem = (rem * 10 + d) % k
                    res += dp(pos + 1, new_tight, new_even_odd_diff, new_rem, new_leading_zero)
                return res
            count = dp(0, True, 0, 0, True)
            total += count
        return total

    return count_upto(high) - count_upto(low - 1)
