import math
from typing import List

def kth_smallest_amount(coins: List[int], k: int) -> int:
    def count(x):
        n = len(coins)
        total = 0
        for mask in range(1, 1 << n):
            current_lcm = 1
            for i in range(n):
                if mask & (1 << i):
                    current_lcm = current_lcm * coins[i] // math.gcd(current_lcm, coins[i])
                    if current_lcm > x:
                        break
            else:
                bits = bin(mask).count('1')
                cnt = x // current_lcm
                if bits % 2 == 1:
                    total += cnt
                else:
                    total -= cnt
        return total

    low = 1
    min_coin = min(coins)
    high = min_coin * k

    while low < high:
        mid = (low + high) // 2
        c = count(mid)
        if c < k:
            low = mid + 1
        else:
            high = mid
    return low
